{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule CobaltStrike_Beacon_Dynamic_DNS {
    meta:
        description = "Detects Cobalt Strike beacons using dynamic DNS domains"
        author = "SOC Team"
        reference = "https://attack.mitre.org/software/S0154/"
        tlp = "amber"
    strings:
        $beacon_config = { 6A 00 68 [2] 00 00 68 [2] 00 00 6A 00 E8 } 
        $dns_query = "[a-zA-Z0-9]{8}\.ddns[0-9]+\.[a-z]{2,}" wide ascii
    condition:
        $beacon_config and $dns_query
}"}, "justification": "LLM proposed: T15_editor_test", "phase": "report", "action": "validate"}, "incident_context": {"incident_id": "d57303e5-a880-55f4-81ba-14550cc656c2", "description": "", "config": "agenticcyops"}}

{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule APT28_Malware_Hash {
