{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule CobaltStrike_Beacon_A1B2C3D4E5F6 {
    meta:
        description = "Detects payload based on hash and known characteristics"
        hash = "a1b2c3d4e5f67890a1b2c3d4e5f67890a1b2c3d4e5f67890a1b2c3d4e5f67890"
