    condition:
        $beacon_config or $mutex or $reg_key
}"}, "justification": "LLM proposed: T15_editor_test", "phase": "report", "action": "validate"}, "incident_context": {"incident_id": "INC-2026-1305", "description": "Threat intelligence feed provides updated IoCs for APT-28 campaign targeting financial sector. Analyze agent writing enriched threat context to M1.", "config": "agenticcyops"}}

