{"proposal": {"tool_id": "T15_editor_test", "arguments": {"rule_type": "yara", "action": "validate", "rule_content": "rule CobaltStrike_Shellcode {
    meta:
        description = "Detects encoded Cobalt Strike shellcode in memory"
        author = "SOC Team"
        severity = 1
    strings:
        $a = { FF E0 }
        $b = { 68 ?? ?? ?? ?? 68 ?? ?? ?? ?? E8 ?? ?? ?? ?? } 
